import { issueKey } from '@projexlight/sdk-vault';
const key = await issueKey({ tier: 'tenant', tenant_id, app_id, owner_id: 'sdk-tenant' });
// key.key_id is the reference to pass into encrypt/decrypt calls.

import { encrypt } from '@projexlight/sdk-vault';
const envelope = await encrypt({ key_id, plaintext: Buffer.from(email, 'utf-8'), context: { person_id } });
// Store envelope.bytes (base64) in the column; envelope.dek_id never leaves vault.

import { startRotationScheduler } from '@projexlight/sdk-vault';
const handle = startRotationScheduler({ intervalMs: 86_400_000 });
// Quiesce on shutdown:
await handle.stop();

import { decrypt, UndecryptableError } from '@projexlight/sdk-vault';
try {
  const plaintext = await decrypt({ envelope, context });
} catch (err) {
  if (err instanceof UndecryptableError) { /* surface to operator + lock tenant */ }
}

import { issueEncounterKey, closeEncounter } from '@projexlight/sdk-vault';
const { key_id } = await issueEncounterKey({ encounter_id });
// ... use key_id for the encounter's encrypt/decrypt ...
await closeEncounter({ encounter_id }); // shreds the key + emits vault.key.shredded.v1.
